// --- Script Logic ---

let html = fs.readFileSync(FILE, 'utf8');

categories.forEach(function(cat) {
  var key = cat.key, need = cat.need, entries = cat.entries;
  var startMarker = 'D.' + key + ' = [';
  var startIdx = html.indexOf(startMarker);
  if (startIdx === -1) { console.log('ERROR: Could not find ' + startMarker); return; }

  var endIdx = html.indexOf('];', startIdx);
  if (endIdx === -1) { console.log('ERROR: Could not find ]; for ' + key); return; }

  var arrayContent = html.substring(startIdx, endIdx);
  var existingCount = (arrayContent.match(/\{n:'/g) || []).length;

  if (existingCount >= entries.length) { console.log(key + ': ' + existingCount + ' entries (all done)'); return; }

  var newEntries = entries.slice(existingCount);
  var insertion = '\n      ' + newEntries.join('\n      ');
  html = html.substring(0, endIdx) + insertion + html.substring(endIdx);

  console.log(key + ': + ' + newEntries.length + ' (' + existingCount + ' -> ' + (existingCount + newEntries.length) + ')');
});

console.log('\n--- Verification ---');
categories.forEach(function(cat) {
  var key = cat.key;
  var s = html.indexOf('D.' + key + ' = [');
  var e = html.indexOf('];', s);
  var c = (html.substring(s, e).match(/\{n:'/g) || []).length;
  console.log(key + ': ' + c + ' entries');
});

fs.writeFileSync(FILE, html, 'utf8');
